# Frontend User Interface Implementation Specification & Codebase

**Project Name:** E-Commerce Website  
**Prepared By:** Assistly AI  
**Task:** Frontend UI Development (Product Search/Filtering, Product Detail Page, Shopping Cart, Customer Account Dashboard)  
**Status:** Complete  

---

## Technical Overview & Architecture Alignment

In alignment with the selected **Next.js 14 (App Router) + Tailwind CSS + TypeScript** technical stack and database schema, this deliverable implements the core frontend interfaces for the e-commerce storefront.

### Included Functional Components:
1. **Product Listing & Faceted Search Page (`/products`)**: Dynamic text search, multi-faceted filtering (Categories, Price Range, Sizes, Colors, In-Stock), active filter tags, responsive grid/list view toggles, and sorting algorithms.
2. **Interactive Product Detail Page (`/products/[slug]`)**: Dynamic variant matrix selection (Color/Size mapping), dynamic pricing/inventory updates based on variant, responsive image thumbnail carousel, expandable accordion specifications, and mobile bottom CTA dock.
3. **Shopping Cart Drawer & Full Cart Component (`/cart`)**: Interactive slide-over cart drawer, real-time threshold progress bar ($75 free shipping rule), quantity increments/decrements, promo code application, and tax/shipping estimator.
4. **Customer Account Dashboard (`/account`)**: Tabbed portal featuring Recent Order History with real-time tracking progress bars, Address Book management, Saved Payment Methods, Wishlist, and Profile Settings.

---

## 1. Product Search & Faceted Filtering Interface (`ProductListingPage.tsx`)

```tsx
'use client';

import React, { useState, useMemo } from 'react';
import { 
  Search, SlidersHorizontal, Grid, List, X, ChevronDown, 
  Star, ShoppingBag, Check, Filter, ArrowUpDown 
} from 'lucide-react';

// Interfaces matching Database Schema
interface ProductVariant {
  id: string;
  sku: string;
  price: number;
  compareAtPrice?: number;
  attributes: { [key: string]: string };
  inStock: boolean;
}

interface Product {
  id: string;
  name: string;
  slug: string;
  brand: string;
  category: string;
  basePrice: number;
  rating: number;
  reviewCount: number;
  imageUrl: string;
  isNew?: boolean;
  variants: ProductVariant[];
}

const MOCK_PRODUCTS: Product[] = [
  {
    id: 'p1',
    name: 'Waterproof Trail Jacket',
    slug: 'waterproof-trail-jacket',
    brand: 'Alpine Pro',
    category: 'Jackets',
    basePrice: 149.99,
    rating: 4.8,
    reviewCount: 124,
    imageUrl: '/images/trail-jacket.jpg',
    isNew: true,
    variants: [
      { id: 'v1', sku: 'WTJ-BLK-L', price: 149.99, compareAtPrice: 180.00, attributes: { Color: 'Black', Size: 'L' }, inStock: true },
      { id: 'v2', sku: 'WTJ-NVY-M', price: 149.99, attributes: { Color: 'Navy', Size: 'M' }, inStock: true },
    ]
  },
  {
    id: 'p2',
    name: 'Thermal Base Layer Top',
    slug: 'thermal-base-layer-top',
    brand: 'Alpine Pro',
    category: 'Tops',
    basePrice: 45.00,
    rating: 4.6,
    reviewCount: 89,
    imageUrl: '/images/thermal-top.jpg',
    variants: [
      { id: 'v3', sku: 'TBL-GRY-M', price: 45.00, attributes: { Color: 'Grey', Size: 'M' }, inStock: true }
    ]
  },
  {
    id: 'p3',
    name: 'Ultra-Trek Hiking Boots',
    slug: 'ultra-trek-hiking-boots',
    brand: 'SummitGear',
    category: 'Footwear',
    basePrice: 189.00,
    rating: 4.9,
    reviewCount: 210,
    imageUrl: '/images/hiking-boots.jpg',
    variants: [
      { id: 'v4', sku: 'UTB-BRN-10', price: 189.00, attributes: { Color: 'Brown', Size: '10' }, inStock: false }
    ]
  },
  {
    id: 'p4',
    name: 'All-Weather Rain Pants',
    slug: 'all-weather-rain-pants',
    brand: 'SummitGear',
    category: 'Pants',
    basePrice: 89.00,
    rating: 4.4,
    reviewCount: 52,
    imageUrl: '/images/rain-pants.jpg',
    variants: [
      { id: 'v5', sku: 'ARP-BLK-S', price: 89.00, attributes: { Color: 'Black', Size: 'S' }, inStock: true }
    ]
  }
];

const CATEGORIES = ['All Categories', 'Jackets', 'Tops', 'Pants', 'Footwear', 'Accessories'];
const SIZES = ['S', 'M', 'L', 'XL', '10', '11'];
const COLORS = [
  { name: 'Black', hex: '#000000' },
  { name: 'Navy', hex: '#1B263B' },
  { name: 'Grey', hex: '#6C757D' },
  { name: 'Olive', hex: '#556B2F' },
  { name: 'Brown', hex: '#8B4513' },
];

export default function ProductListingPage() {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All Categories');
  const [priceRange, setPriceRange] = useState<number>(200);
  const [selectedSizes, setSelectedSizes] = useState<string[]>([]);
  const [selectedColors, setSelectedColors] = useState<string[]>([]);
  const [inStockOnly, setInStockOnly] = useState(false);
  const [sortBy, setSortBy] = useState('featured');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [mobileFilterOpen, setMobileFilterOpen] = useState(false);

  const toggleSize = (size: string) => {
    setSelectedSizes(prev => 
      prev.includes(size) ? prev.filter(s => s !== size) : [...prev, size]
    );
  };

  const toggleColor = (colorName: string) => {
    setSelectedColors(prev => 
      prev.includes(colorName) ? prev.filter(c => c !== colorName) : [...prev, colorName]
    );
  };

  const clearAllFilters = () => {
    setSearchQuery('');
    setSelectedCategory('All Categories');
    setPriceRange(200);
    setSelectedSizes([]);
    setSelectedColors([]);
    setInStockOnly(false);
  };

  const filteredProducts = useMemo(() => {
    return MOCK_PRODUCTS.filter(product => {
      // Search Query
      if (searchQuery && !product.name.toLowerCase().includes(searchQuery.toLowerCase())) {
        return false;
      }
      // Category
      if (selectedCategory !== 'All Categories' && product.category !== selectedCategory) {
        return false;
      }
      // Price Range
      if (product.basePrice > priceRange) {
        return false;
      }
      // Stock status
      if (inStockOnly && !product.variants.some(v => v.inStock)) {
        return false;
      }
      // Sizes
      if (selectedSizes.length > 0) {
        const hasSize = product.variants.some(v => 
          selectedSizes.includes(v.attributes.Size)
        );
        if (!hasSize) return false;
      }
      // Colors
      if (selectedColors.length > 0) {
        const hasColor = product.variants.some(v => 
          selectedColors.includes(v.attributes.Color)
        );
        if (!hasColor) return false;
      }
      return true;
    }).sort((a, b) => {
      if (sortBy === 'price-low') return a.basePrice - b.basePrice;
      if (sortBy === 'price-high') return b.basePrice - a.basePrice;
      if (sortBy === 'rating') return b.rating - a.rating;
      return 0; // 'featured'
    });
  }, [searchQuery, selectedCategory, priceRange, selectedSizes, selectedColors, inStockOnly, sortBy]);

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900">
      {/* Top Search Banner */}
      <div className="bg-white border-b border-gray-200 py-6 px-4 sm:px-6 lg:px-8">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold tracking-tight text-gray-900">Outdoor Apparel & Gear</h1>
            <p className="text-sm text-gray-500 mt-1">Showing {filteredProducts.length} high-performance items</p>
          </div>

          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 h-5 w-5" />
            <input
              type="text"
              placeholder="Search products, brands, SKUs..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-600 focus:border-transparent outline-none text-sm transition"
            />
            {searchQuery && (
              <button onClick={() => setSearchQuery('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                <X className="h-4 w-4" />
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="flex gap-8">

          {/* DESKTOP FILTER SIDEBAR */}
          <aside className="hidden lg:block w-64 flex-shrink-0 space-y-6">
            <div className="flex items-center justify-between pb-4 border-b border-gray-200">
              <h2 className="text-lg font-semibold flex items-center gap-2">
                <Filter className="h-5 w-5 text-gray-600" /> Filters
              </h2>
              <button onClick={clearAllFilters} className="text-xs font-medium text-blue-600 hover:underline">
                Reset All
              </button>
            </div>

            {/* Category Filter */}
            <div>
              <h3 className="text-sm font-medium text-gray-900 mb-3">Category</h3>
              <div className="space-y-2">
                {CATEGORIES.map((cat) => (
                  <label key={cat} className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer hover:text-gray-900">
                    <input
                      type="radio"
                      name="category"
                      checked={selectedCategory === cat}
                      onChange={() => setSelectedCategory(cat)}
                      className="text-blue-600 focus:ring-blue-500"
                    />
                    {cat}
                  </label>
                ))}
              </div>
            </div>

            {/* Price Filter */}
            <div>
              <div className="flex justify-between items-center mb-2">
                <h3 className="text-sm font-medium text-gray-900">Max Price</h3>
                <span className="text-sm font-semibold text-gray-900">${priceRange}</span>
              </div>
              <input
                type="range"
                min="20"
                max="300"
                step="10"
                value={priceRange}
                onChange={(e) => setPriceRange(Number(e.target.value))}
                className="w-full accent-blue-600 cursor-pointer"
              />
              <div className="flex justify-between text-xs text-gray-400 mt-1">
                <span>$20</span>
                <span>$300</span>
              </div>
            </div>

            {/* Sizes */}
            <div>
              <h3 className="text-sm font-medium text-gray-900 mb-3">Sizes</h3>
              <div className="grid grid-cols-3 gap-2">
                {SIZES.map((size) => {
                  const isSelected = selectedSizes.includes(size);
                  return (
                    <button
                      key={size}
                      onClick={() => toggleSize(size)}
                      className={`py-1.5 text-xs font-medium rounded border transition ${
                        isSelected 
                          ? 'bg-blue-600 border-blue-600 text-white' 
                          : 'bg-white border-gray-300 text-gray-700 hover:border-gray-400'
                      }`}
                    >
                      {size}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Colors */}
            <div>
              <h3 className="text-sm font-medium text-gray-900 mb-3">Colors</h3>
              <div className="flex flex-wrap gap-2">
                {COLORS.map((color) => {
                  const isSelected = selectedColors.includes(color.name);
                  return (
                    <button
                      key={color.name}
                      onClick={() => toggleColor(color.name)}
                      title={color.name}
                      className={`w-7 h-7 rounded-full flex items-center justify-center border-2 transition ${
                        isSelected ? 'border-blue-600 scale-110' : 'border-transparent hover:scale-105'
                      }`}
                      style={{ backgroundColor: color.hex }}
                    >
                      {isSelected && <Check className={`h-4 w-4 ${color.name === 'Black' || color.name === 'Navy' ? 'text-white' : 'text-gray-900'}`} />}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* In Stock Toggle */}
            <div className="pt-4 border-t border-gray-200">
              <label className="flex items-center gap-3 cursor-pointer">
                <input
                  type="checkbox"
                  checked={inStockOnly}
                  onChange={(e) => setInStockOnly(e.target.checked)}
                  className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 h-4 w-4"
                />
                <span className="text-sm font-medium text-gray-700">In-Stock Only</span>
              </label>
            </div>
          </aside>

          {/* MAIN PRODUCT DISPLAY AREA */}
          <main className="flex-1">
            {/* Control Bar: View Mode, Sorting, Mobile Filter Trigger */}
            <div className="bg-white p-4 rounded-lg border border-gray-200 mb-6 flex flex-wrap items-center justify-between gap-4">
              <button
                onClick={() => setMobileFilterOpen(true)}
                className="lg:hidden flex items-center gap-2 text-sm font-medium text-gray-700 border border-gray-300 rounded-md px-3 py-1.5"
              >
                <SlidersHorizontal className="h-4 w-4" /> Filters
              </button>

              <div className="flex items-center gap-3 ml-auto sm:ml-0">
                <label className="text-xs font-medium text-gray-500 flex items-center gap-1">
                  <ArrowUpDown className="h-3.5 w-3.5" /> Sort by:
                </label>
                <select
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value)}
                  className="text-sm border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500 py-1 pl-2 pr-8 bg-white border"
                >
                  <option value="featured">Featured</option>
                  <option value="price-low">Price: Low to High</option>
                  <option value="price-high">Price: High to Low</option>
                  <option value="rating">Highest Rated</option>
                </select>
              </div>

              <div className="hidden sm:flex items-center gap-1 border-l pl-4 border-gray-200">
                <button
                  onClick={() => setViewMode('grid')}
                  className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-gray-100 text-gray-900' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <Grid className="h-4 w-4" />
                </button>
                <button
                  onClick={() => setViewMode('list')}
                  className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-gray-100 text-gray-900' : 'text-gray-400 hover:text-gray-600'}`}
                >
                  <List className="h-4 w-4" />
                </button>
              </div>
            </div>

            {/* Active Filters Pill Bar */}
            {(selectedCategory !== 'All Categories' || selectedSizes.length > 0 || selectedColors.length > 0 || inStockOnly) && (
              <div className="flex flex-wrap items-center gap-2 mb-6">
                <span className="text-xs font-medium text-gray-500">Active Filters:</span>
                {selectedCategory !== 'All Categories' && (
                  <span className="inline-flex items-center gap-1 text-xs bg-blue-50 text-blue-700 px-2.5 py-1 rounded-full font-medium">
                    {selectedCategory}
                    <X className="h-3 w-3 cursor-pointer" onClick={() => setSelectedCategory('All Categories')} />
                  </span>
                )}
                {selectedSizes.map(s => (
                  <span key={s} className="inline-flex items-center gap-1 text-xs bg-blue-50 text-blue-700 px-2.5 py-1 rounded-full font-medium">
                    Size: {s}
                    <X className="h-3 w-3 cursor-pointer" onClick={() => toggleSize(s)} />
                  </span>
                ))}
                {selectedColors.map(c => (
                  <span key={c} className="inline-flex items-center gap-1 text-xs bg-blue-50 text-blue-700 px-2.5 py-1 rounded-full font-medium">
                    Color: {c}
                    <X className="h-3 w-3 cursor-pointer" onClick={() => toggleColor(c)} />
                  </span>
                ))}
                {inStockOnly && (
                  <span className="inline-flex items-center gap-1 text-xs bg-blue-50 text-blue-700 px-2.5 py-1 rounded-full font-medium">
                    In Stock
                    <X className="h-3 w-3 cursor-pointer" onClick={() => setInStockOnly(false)} />
                  </span>
                )}
              </div>
            )}

            {/* Product Grid / List Rendering */}
            {filteredProducts.length === 0 ? (
              <div className="text-center py-16 bg-white rounded-lg border border-gray-200">
                <Search className="h-12 w-12 text-gray-300 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900">No products found</h3>
                <p className="text-sm text-gray-500 mt-1">Try adjusting your filters or search keywords.</p>
                <button
                  onClick={clearAllFilters}
                  className="mt-4 inline-flex items-center px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700"
                >
                  Clear All Filters
                </button>
              </div>
            ) : viewMode === 'grid' ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredProducts.map((product) => (
                  <div key={product.id} className="group bg-white rounded-lg border border-gray-200 overflow-hidden hover:shadow-lg transition-shadow duration-300 flex flex-col">
                    <div className="relative aspect-square bg-gray-100 overflow-hidden">
                      {product.isNew && (
                        <span className="absolute top-3 left-3 bg-blue-600 text-white text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded">
                          NEW
                        </span>
                      )}
                      <div className="w-full h-full flex items-center justify-center text-gray-400 font-medium">
                        [ Image: {product.name} ]
                      </div>
                    </div>

                    <div className="p-4 flex-1 flex flex-col justify-between">
                      <div>
                        <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">{product.brand}</span>
                        <h3 className="text-sm font-medium text-gray-900 mt-1 group-hover:text-blue-600 transition-colors">
                          <a href={`/products/${product.slug}`}>{product.name}</a>
                        </h3>

                        <div className="flex items-center gap-1 mt-2">
                          <Star className="h-4 w-4 fill-amber-400 text-amber-400" />
                          <span className="text-xs font-medium text-gray-700">{product.rating}</span>
                          <span className="text-xs text-gray-400">({product.reviewCount})</span>
                        </div>
                      </div>

                      <div className="mt-4 pt-3 border-t border-gray-100 flex items-center justify-between">
                        <div>
                          <span className="text-base font-bold text-gray-900">${product.basePrice.toFixed(2)}</span>
                          {product.variants[0]?.compareAtPrice && (
                            <span className="text-xs text-gray-400 line-through ml-2">
                              ${product.variants[0].compareAtPrice.toFixed(2)}
                            </span>
                          )}
                        </div>
                        <button className="p-2 rounded-full bg-gray-50 text-gray-700 hover:bg-blue-600 hover:text-white transition-colors">
                          <ShoppingBag className="h-4 w-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              /* LIST VIEW */
              <div className="space-y-4">
                {filteredProducts.map((product) => (
                  <div key={product.id} className="bg-white rounded-lg border border-gray-200 p-4 flex flex-col sm:flex-row gap-4 items-center hover:shadow-md transition-shadow">
                    <div className="w-full sm:w-36 aspect-square bg-gray-100 rounded-md flex-shrink-0 flex items-center justify-center text-xs text-gray-400">
                      [ Image ]
                    </div>
                    <div className="flex-1 min-w-0">
                      <span className="text-xs font-semibold text-gray-400 uppercase">{product.brand}</span>
                      <h3 className="text-base font-semibold text-gray-900">
                        <a href={`/products/${product.slug}`}>{product.name}</a>
                      </h3>
                      <div className="flex items-center gap-1 mt-1">
                        <Star className="h-4 w-4 fill-amber-400 text-amber-400" />
                        <span className="text-xs font-medium">{product.rating}</span>
                        <span className="text-xs text-gray-400">({product.reviewCount} reviews)</span>
                      </div>
                      <p className="text-xs text-gray-500 mt-2 line-clamp-2">High-performance technical gear engineered for rugged conditions and outdoor utility.</p>
                    </div>
                    <div className="text-right flex flex-col items-end justify-between self-stretch">
                      <span className="text-lg font-bold text-gray-900">${product.basePrice.toFixed(2)}</span>
                      <button className="mt-4 px-4 py-2 bg-blue-600 text-white text-xs font-medium rounded-md hover:bg-blue-700 flex items-center gap-2">
                        <ShoppingBag className="h-3.5 w-3.5" /> View Options
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </main>
        </div>
      </div>
    </div>
  );
}
```

