## 2. Interactive Product Detail Page (`ProductDetailPage.tsx`)

```tsx
'use client';

import React, { useState } from 'react';
import { 
  Star, ShieldCheck, Truck, RotateCcw, ChevronRight, 
  Minus, Plus, ShoppingCart, Zap, Heart, Share2, Check 
} from 'lucide-react';

interface Variant {
  id: string;
  sku: string;
  color: string;
  size: string;
  price: number;
  compareAtPrice?: number;
  stockQty: number;
}

const PRODUCT_DATA = {
  id: 'p101',
  name: 'Waterproof Trail Jacket',
  brand: 'Alpine Pro',
  sku: 'WTJ-BASE',
  rating: 4.8,
  reviewCount: 124,
  description: 'Engineered for extreme alpine conditions, the Waterproof Trail Jacket features a 3-layer breathable membrane, fully taped seams, and weather-defying zippers.',
  features: [
    '20,000mm Waterproof Rating',
    'Breathable 3-layer GORE-TEX technology',
    'Helmet-compatible adjustable hood',
    'Underarm pit zips for rapid ventilation',
    'Reinforced ripstop abrasion zones'
  ],
  colors: [
    { name: 'Black', hex: '#000000' },
    { name: 'Navy', hex: '#1B263B' },
    { name: 'Olive', hex: '#556B2F' }
  ],
  sizes: ['S', 'M', 'L', 'XL'],
  variants: [
    { id: 'v1', sku: 'WTJ-BLK-S', color: 'Black', size: 'S', price: 149.99, compareAtPrice: 180.00, stockQty: 12 },
    { id: 'v2', sku: 'WTJ-BLK-M', color: 'Black', size: 'M', price: 149.99, compareAtPrice: 180.00, stockQty: 4 },
    { id: 'v3', sku: 'WTJ-BLK-L', color: 'Black', size: 'L', price: 149.99, compareAtPrice: 180.00, stockQty: 8 },
    { id: 'v4', sku: 'WTJ-BLK-XL', color: 'Black', size: 'XL', price: 159.99, stockQty: 0 }, // Out of stock example
    { id: 'v5', sku: 'WTJ-NVY-M', color: 'Navy', size: 'M', price: 149.99, stockQty: 15 },
  ] as Variant[]
};

export default function ProductDetailPage() {
  const [selectedColor, setSelectedColor] = useState('Black');
  const [selectedSize, setSelectedSize] = useState('L');
  const [quantity, setQuantity] = useState(1);
  const [activeTab, setActiveTab] = useState<'overview' | 'specs' | 'reviews'>('overview');
  const [selectedImageIndex, setSelectedImageIndex] = useState(0);

  // Find active variant matching choices
  const currentVariant = PRODUCT_DATA.variants.find(
    v => v.color === selectedColor && v.size === selectedSize
  ) || PRODUCT_DATA.variants[0];

  const handleQuantityChange = (delta: number) => {
    setQuantity(prev => Math.max(1, Math.min(prev + delta, currentVariant.stockQty || 1)));
  };

  const images = [
    '/images/products/trail-jacket-1.jpg',
    '/images/products/trail-jacket-2.jpg',
    '/images/products/trail-jacket-3.jpg',
    '/images/products/trail-jacket-4.jpg'
  ];

  return (
    <div className="bg-white min-h-screen pb-24 lg:pb-12 text-gray-900">
      {/* Breadcrumb */}
      <nav className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 text-xs text-gray-500 flex items-center gap-2">
        <a href="/" className="hover:text-gray-900">Home</a>
        <ChevronRight className="h-3 w-3" />
        <a href="/apparel" className="hover:text-gray-900">Apparel</a>
        <ChevronRight className="h-3 w-3" />
        <a href="/apparel/jackets" className="hover:text-gray-900">Jackets</a>
        <ChevronRight className="h-3 w-3" />
        <span className="text-gray-900 font-medium truncate">{PRODUCT_DATA.name}</span>
