## 3. Shopping Cart Drawer & Full Cart Component (`ShoppingCart.tsx`)

```tsx
'use client';

import React, { useState } from 'react';
import { 
  X, Trash2, Plus, Minus, ShoppingBag, ArrowRight, 
  Shield, Truck, Tag 
} from 'lucide-react';

interface CartItem {
  id: string;
  variantId: string;
  name: string;
  color: string;
  size: string;
  price: number;
  quantity: number;
  imageUrl: string;
}

const INITIAL_CART: CartItem[] = [
  {
    id: 'c1',
    variantId: 'v3',
    name: 'Waterproof Trail Jacket',
    color: 'Black',
    size: 'L',
    price: 149.99,
    quantity: 1,
    imageUrl: '/images/trail-jacket.jpg'
  },
  {
    id: 'c2',
    variantId: 'v8',
    name: 'Thermal Wool Hiking Socks',
    color: 'Grey',
    size: 'M',
    price: 18.00,
    quantity: 2,
    imageUrl: '/images/socks.jpg'
  }
];

const FREE_SHIPPING_THRESHOLD = 75.00;

export default function ShoppingCartDrawer({ isOpen = true, onClose = () => {} }) {
  const [cartItems, setCartItems] = useState<CartItem[]>(INITIAL_CART);
  const [promoCode, setPromoCode] = useState('');
  const [discount, setDiscount] = useState(0);
  const [promoError, setPromoError] = useState('');

  const updateQuantity = (id: string, delta: number) => {
    setCartItems(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const removeItem = (id: string) => {
    setCartItems(prev => prev.filter(item => item.id !== id));
  };

  const applyPromoCode = (e: React.FormEvent) => {
    e.preventDefault();
    if (promoCode.toUpperCase() === 'SAVE10') {
      setDiscount(10);
      setPromoError('');
    } else {
      setPromoError('Invalid coupon code');
    }
  };

  const subtotal = cartItems.reduce((sum, item) => sum + (item.price * item.quantity), 0);
  const totalAfterDiscount = Math.max(0, subtotal - discount);
  const amountToFreeShipping = Math.max(0, FREE_SHIPPING_THRESHOLD - subtotal);
  const freeShippingProgress = Math.min(100, (subtotal / FREE_SHIPPING_THRESHOLD) * 100);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-hidden bg-black/50 backdrop-blur-sm flex justify-end">
      <div className="w-full max-w-md bg-white h-full flex flex-col shadow-2xl animate-in slide-in-from-right duration-300">

        {/* Cart Header */}
        <div className="p-4 border-b border-gray-200 flex items-center justify-between bg-gray-50">
          <div className="flex items-center gap-2">
            <ShoppingBag className="h-5 w-5 text-gray-700" />
            <h2 className="text-lg font-bold text-gray-900">Your Cart ({cartItems.length})</h2>
          </div>
          <button onClick={onClose} className="p-1 text-gray-400 hover:text-gray-600 rounded-md">
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Free Shipping Progress Indicator (BRD Compliance) */}
        <div className="bg-blue-50 p-3 border-b border-blue-100">
          <div className="flex justify-between items-center text-xs font-semibold mb-1">
            {amountToFreeShipping === 0 ? (
              <span className="text-green-700 flex items-center gap-1 font-bold">
                <Truck className="h-3.5 w-3.5" /> You unlocked Free Express Shipping!
              </span>
            ) : (
              <span className="text-blue-900">
                Add <span className="font-bold">${amountToFreeShipping.toFixed(2)}</span> more for FREE Shipping
              </span>
            )}
            <span className="text-blue-700 font-bold">{Math.round(freeShippingProgress)}%</span>
          </div>
          <div className="w-full bg-blue-200 h-2 rounded-full overflow-hidden">
            <div 
              className="bg-blue-600 h-full transition-all duration-300" 
              style={{ width: `${freeShippingProgress}%` }}
            />
          </div>
        </div>

        {/* Cart Item List */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {cartItems.length === 0 ? (
            <div className="text-center py-12">
              <ShoppingBag className="h-12 w-12 text-gray-300 mx-auto mb-3" />
              <p className="text-gray-500 font-medium">Your shopping cart is empty.</p>
              <button onClick={onClose} className="mt-4 px-4 py-2 bg-blue-600 text-white text-xs font-bold rounded-md">
                Start Shopping
              </button>
            </div>
          ) : (
            cartItems.map((item) => (
              <div key={item.id} className="flex gap-4 p-3 bg-gray-50 rounded-lg border border-gray-200">
                <div className="w-20 h-20 bg-gray-200 rounded-md flex-shrink-0 flex items-center justify-center text-[10px] text-gray-400">
                  [ Img ]
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex justify-between items-start">
                    <h3 className="text-sm font-semibold text-gray-900 truncate">{item.name}</h3>
                    <button onClick={() => removeItem(item.id)} className="text-gray-400 hover:text-red-600">
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                  <p className="text-xs text-gray-500 mt-0.5">Color: {item.color} | Size: {item.size}</p>

                  <div className="flex items-center justify-between mt-3">
                    <div className="flex items-center border border-gray-300 rounded bg-white">
                      <button onClick={() => updateQuantity(item.id, -1)} className="px-2 py-0.5 text-gray-600 hover:bg-gray-100">
                        <Minus className="h-3 w-3" />
                      </button>
                      <span className="px-2 text-xs font-bold text-gray-800">{item.quantity}</span>
                      <button onClick={() => updateQuantity(item.id, 1)} className="px-2 py-0.5 text-gray-600 hover:bg-gray-100">
                        <Plus className="h-3 w-3" />
                      </button>
                    </div>
                    <span className="text-sm font-bold text-gray-900">${(item.price * item.quantity).toFixed(2)}</span>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Promo Code & Order Summary Footer */}
        {cartItems.length > 0 && (
          <div className="p-4 border-t border-gray-200 bg-white space-y-3">

            {/* Coupon Input */}
            <form onSubmit={applyPromoCode} className="flex gap-2">
              <div className="relative flex-1">
                <Tag className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-gray-400" />
                <input
                  type="text"
                  placeholder="Promo Code (e.g. SAVE10)"
                  value={promoCode}
                  onChange={(e) => setPromoCode(e.target.value)}
                  className="w-full pl-8 pr-3 py-1.5 text-xs border border-gray-300 rounded focus:ring-1 focus:ring-blue-600 outline-none uppercase"
                />
              </div>
              <button type="submit" className="px-3 py-1.5 bg-gray-900 text-white text-xs font-bold rounded hover:bg-gray-800">
                Apply
              </button>
            </form>
            {promoError && <p className="text-[11px] text-red-600">{promoError}</p>}
            {discount > 0 && <p className="text-[11px] text-green-600 font-semibold">Promo applied: -${discount.toFixed(2)} off</p>}

            {/* Calculations */}
            <div className="space-y-1.5 text-xs border-t border-gray-100 pt-3">
              <div className="flex justify-between text-gray-600">
                <span>Subtotal</span>
                <span className="font-semibold text-gray-900">${subtotal.toFixed(2)}</span>
              </div>
              {discount > 0 && (
                <div className="flex justify-between text-green-600">
                  <span>Discount</span>
                  <span>-${discount.toFixed(2)}</span>
                </div>
              )}
              <div className="flex justify-between text-gray-600">
                <span>Estimated Shipping</span>
                <span>{amountToFreeShipping === 0 ? 'FREE' : '$5.99'}</span>
              </div>
              <div className="flex justify-between text-base font-bold text-gray-900 border-t border-gray-200 pt-2">
                <span>Estimated Total</span>
                <span>${(totalAfterDiscount + (amountToFreeShipping === 0 ? 0 : 5.99)).toFixed(2)}</span>
              </div>
            </div>

            {/* Checkout Action */}
            <a 
              href="/checkout" 
              className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold text-sm rounded-lg flex items-center justify-center gap-2 shadow-md transition"
            >
              Proceed to Checkout <ArrowRight className="h-4 w-4" />
            </a>

            <div className="flex items-center justify-center gap-2 text-[11px] text-gray-400 pt-1">
              <Shield className="h-3.5 w-3.5" /> 256-Bit SSL Encrypted Checkout
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
