## 2. Automated Inventory Tracking & Allocation Engine (`InventoryService.ts`)

Concurrency during high-volume sales (e.g., flash sales) requires row-level locking (`SELECT FOR UPDATE`) to prevent double-selling. The service separates **Available Stock** from **Reserved Stock**.

```typescript
import { PrismaClient, InventoryLogType } from '@prisma/client';

const prisma = new PrismaClient();

export interface InventoryReservationItem {
  variantId: string;
  quantity: number;
}

export class InventoryService {
  /**
   * ATOMIC STOCK RESERVATION
   * Executes inside a raw SQL database transaction to acquire row-level locks on InventoryLevels.
   * Prevents race conditions and negative stock balances.
   */
  public async reserveInventory(
    orderId: string,
    locationId: string,
    items: InventoryReservationItem[]
  ): Promise<{ success: boolean; message?: string }> {
    return await prisma.$transaction(async (tx) => {
      for (const item of items) {
        // Step 1: Lock the row using raw SQL (SELECT ... FOR UPDATE)
        const lockedInventory: Array<{ id: string; available_qty: number; reserved_qty: number }> = 
          await tx.$queryRaw`
            SELECT id, available_qty, reserved_qty 
            FROM inventory_levels 
            WHERE variant_id = ${item.variantId}::uuid AND location_id = ${locationId}::uuid 
            FOR UPDATE
          `;

        if (!lockedInventory || lockedInventory.length === 0) {
          throw new Error(`Inventory record not found for variant ${item.variantId} at location ${locationId}`);
        }

        const currentStock = lockedInventory[0];

        // Step 2: Validate available quantity
        if (currentStock.available_qty < item.quantity) {
          throw new Error(`Insufficient stock for variant ${item.variantId}. Required: ${item.quantity}, Available: ${currentStock.available_qty}`);
        }

        // Step 3: Move stock from available_qty to reserved_qty
        await tx.inventoryLevel.update({
          where: { id: currentStock.id },
          data: {
            availableQty: { decrement: item.quantity },
            reservedQty: { increment: item.quantity },
          },
        });

        // Step 4: Write immutable audit log
        await tx.inventoryLog.create({
          data: {
            variantId: item.variantId,
            locationId: locationId,
            quantityDelta: -item.quantity,
            type: InventoryLogType.ORDER_RESERVATION,
            referenceId: orderId,
            notes: `Stock reserved for Order ${orderId}`,
          },
        });
      }

      return { success: true };
    });
  }

  /**
   * COMMIT RESERVED INVENTORY (On Payment Succeeded / Order Dispatch)
   * Deducts quantity permanently from reservedQty.
   */
  public async commitInventory(
    orderId: string,
    locationId: string,
    items: InventoryReservationItem[]
  ): Promise<void> {
    await prisma.$transaction(async (tx) => {
      for (const item of items) {
        await tx.inventoryLevel.update({
          where: {
            variantId_locationId: {
              variantId: item.variantId,
              locationId: locationId,
            },
          },
          data: {
            reservedQty: { decrement: item.quantity },
          },
        });

        await tx.inventoryLog.create({
          data: {
            variantId: item.variantId,
            locationId: locationId,
            quantityDelta: 0,
            type: InventoryLogType.ORDER_FULFILLMENT,
            referenceId: orderId,
            notes: `Inventory reserved stock committed/fulfilled for Order ${orderId}`,
          },
        });
      }
    });
  }

  /**
   * RELEASE RESERVED INVENTORY (On Payment Failure, Abandonment, or Order Cancellation)
   * Restores reservedQty back into availableQty.
   */
  public async releaseInventory(
    orderId: string,
    locationId: string,
    items: InventoryReservationItem[]
  ): Promise<void> {
    await prisma.$transaction(async (tx) => {
      for (const item of items) {
        await tx.inventoryLevel.update({
          where: {
            variantId_locationId: {
              variantId: item.variantId,
              locationId: locationId,
            },
          },
          data: {
            availableQty: { increment: item.quantity },
            reservedQty: { decrement: item.quantity },
          },
        });

        await tx.inventoryLog.create({
          data: {
            variantId: item.variantId,
            locationId: locationId,
            quantityDelta: item.quantity,
            type: InventoryLogType.CANCELLATION_RESTOCK,
            referenceId: orderId,
            notes: `Stock reservation released back to available inventory for Order ${orderId}`,
          },
        });
      }
    });
  }

  /**
   * REORDER THRESHOLD MONITORING
   * Checks if variant inventory falls below specified reorder point.
   */
  public async checkLowStockAlerts(variantId: string, locationId: string): Promise<boolean> {
    const level = await prisma.inventoryLevel.findUnique({
      where: {
        variantId_locationId: { variantId, locationId },
      },
    });

    if (level && level.availableQty <= level.reorderPoint) {
      console.warn(`[LOW STOCK ALERT] Variant ${variantId} at Location ${locationId} is at ${level.availableQty} units (Reorder Threshold: ${level.reorderPoint})`);
      // Trigger notification service, webhook, or automated purchase order generation
      return true;
    }
    return false;
  }
}
```

