## 3. Payment Gateway Integration Service (`PaymentService.ts`)

Integrates directly with the **Stripe API SDK** using modern payment intent patterns (supporting Cards, Apple Pay, Google Pay, and Klarna with 3D Secure 2.0).

```typescript
import Stripe from 'stripe';
import { PrismaClient, PaymentStatus, PaymentMethod } from '@prisma/client';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || 'sk_test_mock_key', {
  apiVersion: '2023-10-16',
});

const prisma = new PrismaClient();

export interface CreatePaymentIntentParams {
  orderId: string;
  amount: number; // Amount in Dollars
  currency: string;
  customerEmail: string;
  paymentMethodType?: string;
}

export class PaymentService {
  /**
   * Creates a Stripe PaymentIntent bound to an Internal Order ID
   */
  public async createPaymentIntent(params: CreatePaymentIntentParams): Promise<{
    clientSecret: string;
    paymentIntentId: string;
  }> {
    const amountInCents = Math.round(params.amount * 100);

    const paymentIntent = await stripe.paymentIntents.create({
      amount: amountInCents,
      currency: params.currency.toLowerCase(),
      receipt_email: params.customerEmail,
      automatic_payment_methods: { enabled: true },
      metadata: {
        orderId: params.orderId,
        customerEmail: params.customerEmail,
      },
    });

    // Record initial transaction attempt
    await prisma.paymentTransaction.create({
      data: {
        orderId: params.orderId,
        gateway: 'STRIPE',
        transactionRef: paymentIntent.id,
        paymentMethod: PaymentMethod.CREDIT_CARD,
        amount: params.amount,
        currency: params.currency,
        status: PaymentStatus.UNPAID,
        rawResponse: JSON.parse(JSON.stringify(paymentIntent)),
      },
    });

    return {
      clientSecret: paymentIntent.client_secret!,
      paymentIntentId: paymentIntent.id,
    };
  }

  /**
   * Process Refund logic
   */
  public async processRefund(orderId: string, amount?: number): Promise<boolean> {
    const transaction = await prisma.paymentTransaction.findFirst({
      where: { orderId, status: PaymentStatus.PAID },
    });

    if (!transaction) {
      throw new Error(`No paid transaction found for order ${orderId}`);
    }

    const refund = await stripe.refunds.create({
      payment_intent: transaction.transactionRef,
      amount: amount ? Math.round(amount * 100) : undefined, // Full refund if undefined
    });

    if (refund.status === 'succeeded') {
      await prisma.paymentTransaction.create({
        data: {
          orderId,
          gateway: 'STRIPE',
          transactionRef: refund.id,
          paymentMethod: transaction.paymentMethod,
          amount: amount || Number(transaction.amount),
          currency: transaction.currency,
          status: PaymentStatus.REFUNDED,
          rawResponse: JSON.parse(JSON.stringify(refund)),
        },
      });

      await prisma.order.update({
        where: { id: orderId },
        data: {
          status: 'REFUNDED',
          paymentStatus: PaymentStatus.REFUNDED,
        },
      });

      return true;
    }

    return false;
  }
}
```

### Stripe Webhook Handler (`stripeWebhook.ts`)

Processes asynchronous events from Stripe (e.g. dynamic 3DS authentication completions or async offline payments), ensuring signature validation and idempotency.

```typescript
import { Request, Response } from 'express';
import Stripe from 'stripe';
import { OrderProcessingService } from './OrderProcessingService';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || 'sk_test_mock_key', {
  apiVersion: '2023-10-16',
});

const orderProcessingService = new OrderProcessingService();

export async function handleStripeWebhook(req: Request, res: Response) {
  const sig = req.headers['stripe-signature'];
  const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET || 'whsec_mock_key';

  let event: Stripe.Event;

  try {
    // Verify raw payload signature against Stripe Secret Key
    event = stripe.webhooks.constructEvent(req.body, sig as string, endpointSecret);
  } catch (err: any) {
    console.error(`Webhook Signature Verification Failed: ${err.message}`);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Idempotent Event Handling
  switch (event.type) {
    case 'payment_intent.succeeded': {
      const paymentIntent = event.data.object as Stripe.PaymentIntent;
      const orderId = paymentIntent.metadata.orderId;

      console.log(`[WEBHOOK] PaymentIntent succeeded for Order ID: ${orderId}`);
      await orderProcessingService.handlePaymentSuccess(orderId, paymentIntent.id);
      break;
    }

    case 'payment_intent.payment_failed': {
      const paymentIntent = event.data.object as Stripe.PaymentIntent;
      const orderId = paymentIntent.metadata.orderId;

      console.warn(`[WEBHOOK] PaymentIntent failed for Order ID: ${orderId}`);
      await orderProcessingService.handlePaymentFailure(orderId, paymentIntent.last_payment_error?.message);
      break;
    }

    default:
      console.log(`Unhandled Stripe event type: ${event.type}`);
  }

  res.status(200).json({ received: true });
}
