## 4. Secure Order Processing Engine (`OrderProcessingService.ts`)

Coordinates validation, calculations, stock reservations, order entity creation, payment execution, and fulfillment transitions.

```typescript
import { PrismaClient, OrderStatus, PaymentStatus } from '@prisma/client';
import { InventoryService } from './InventoryService';
import { PaymentService } from './PaymentService';

const prisma = new PrismaClient();
const inventoryService = new InventoryService();
const paymentService = new PaymentService();

// Primary location ID for fulfillment (matches default warehouse)
const PRIMARY_LOCATION_ID = 'e2b3c4d5-e6f7-8a9b-0c1d-2e3f4a5b6c7d';

export interface OrderItemInput {
  variantId: string;
  quantity: number;
}

export interface CreateOrderDTO {
  customerId?: string;
  customerEmail: string;
  customerPhone?: string;
  items: OrderItemInput[];
  shippingAddress: {
    firstName: string;
    lastName: string;
    addressLine1: string;
    addressLine2?: string;
    city: string;
    state: string;
    postalCode: string;
    country: string;
  };
  shippingMethod: string;
  promoCode?: string;
}

export class OrderProcessingService {
  /**
   * SECURE ORDER CREATION & INITIALIZATION
   * 1. Re-verifies catalog pricing on server (never trusts frontend prices).
   * 2. Calculates real-time tax and flat/tiered shipping rules.
   * 3. Atomically reserves inventory.
   * 4. Creates Order, ShippingAddress, OrderItems in DB.
   * 5. Initializes Stripe PaymentIntent.
   */
  public async createOrder(dto: CreateOrderDTO): Promise<{
    orderId: string;
    orderNumber: string;
    grandTotal: number;
    clientSecret: string;
  }> {
    // Step 1: Server-side validation of variants & prices
    let calculatedSubtotal = 0;
    const validatedItems: Array<{
      variantId: string;
      unitPrice: number;
      quantity: number;
    }> = [];

    for (const item of dto.items) {
      const variant = await prisma.productVariant.findUnique({
        where: { id: item.variantId },
        include: { product: true },
      });

      if (!variant || !variant.isActive) {
        throw new Error(`Product variant ${item.variantId} is unavailable.`);
      }

      const unitPrice = Number(variant.price);
      calculatedSubtotal += unitPrice * item.quantity;

      validatedItems.push({
        variantId: variant.id,
        unitPrice,
        quantity: item.quantity,
      });
    }

    // Step 2: Calculate Discounts, Tax, & Shipping based on BRD Rules
    let discountTotal = 0;
    if (dto.promoCode === 'SAVE10') {
      discountTotal = 10.00;
    }

    const subtotalAfterDiscount = Math.max(0, calculatedSubtotal - discountTotal);

    // Business Rule: Free Express Shipping over $75.00
    let shippingTotal = 0.00;
    if (subtotalAfterDiscount < 75.00) {
      shippingTotal = dto.shippingMethod === 'EXPRESS' ? 14.99 : 5.99;
    }

    // Tax Engine Calculation (Simulated 8.25% Destination Rate)
    const taxTotal = Math.round(subtotalAfterDiscount * 0.0825 * 100) / 100;
    const grandTotal = Math.round((subtotalAfterDiscount + shippingTotal + taxTotal) * 100) / 100;

    const orderNumber = `ORD-${Date.now().toString().slice(-6)}-${Math.floor(1000 + Math.random() * 9000)}`;

    // Step 3: Transactional Database Operations & Inventory Reservation
    const newOrder = await prisma.$transaction(async (tx) => {
      const order = await tx.order.create({
        data: {
          orderNumber,
          customerId: dto.customerId,
          customerEmail: dto.customerEmail,
          customerPhone: dto.customerPhone,
          status: OrderStatus.PENDING_PAYMENT,
          paymentStatus: PaymentStatus.UNPAID,
          subtotal: calculatedSubtotal,
          discountTotal: discountTotal,
          taxTotal: taxTotal,
          shippingTotal: shippingTotal,
          grandTotal: grandTotal,
          currency: 'USD',
          promoCode: dto.promoCode,
          shippingMethod: dto.shippingMethod,
          shippingAddress: {
            create: { ...dto.shippingAddress },
          },
          items: {
            create: validatedItems.map((vi) => ({
              variantId: vi.variantId,
              unitPrice: vi.unitPrice,
              quantity: vi.quantity,
            })),
          },
        },
      });

      return order;
    });

    // Step 4: Atomic Inventory Reservation
    try {
      await inventoryService.reserveInventory(
        newOrder.id,
        PRIMARY_LOCATION_ID,
        dto.items.map(i => ({ variantId: i.variantId, quantity: i.quantity }))
      );
    } catch (err: any) {
      // If inventory allocation fails, rollback Order status
      await prisma.order.update({
        where: { id: newOrder.id },
        data: { status: OrderStatus.CANCELLED },
      });
      throw err;
    }

    // Step 5: Initialize Payment Intent with Gateway
    const paymentResult = await paymentService.createPaymentIntent({
      orderId: newOrder.id,
      amount: grandTotal,
      currency: 'USD',
      customerEmail: dto.customerEmail,
    });

    return {
      orderId: newOrder.id,
      orderNumber: newOrder.orderNumber,
      grandTotal: grandTotal,
      clientSecret: paymentResult.clientSecret,
    };
  }

  /**
   * HANDLE SUCCESSFUL PAYMENT (Called by Webhook / Payment Completion)
   */
  public async handlePaymentSuccess(orderId: string, transactionRef: string): Promise<void> {
    const order = await prisma.order.findUnique({
      where: { id: orderId },
      include: { items: true },
    });

    if (!order) {
      throw new Error(`Order not found: ${orderId}`);
    }

    if (order.paymentStatus === PaymentStatus.PAID) {
      console.log(`Order ${orderId} already marked as paid.`);
      return;
    }

    // Update Transaction & Order Status
    await prisma.$transaction([
      prisma.paymentTransaction.updateMany({
        where: { orderId, transactionRef },
        data: { status: PaymentStatus.PAID },
      }),
      prisma.order.update({
        where: { id: orderId },
        data: {
          status: OrderStatus.PROCESSING,
          paymentStatus: PaymentStatus.PAID,
        },
      }),
    ]);

    // Commit inventory permanently from reserved
    await inventoryService.commitInventory(
      order.id,
      PRIMARY_LOCATION_ID,
      order.items.map(i => ({ variantId: i.variantId, quantity: i.quantity }))
    );

    // Trigger transactional confirmation email
    await this.sendOrderConfirmationEmail(order.customerEmail, order.orderNumber);
  }

  /**
   * HANDLE PAYMENT FAILURE (Called by Webhook / Timeout)
   */
  public async handlePaymentFailure(orderId: string, reason?: string): Promise<void> {
    const order = await prisma.order.findUnique({
      where: { id: orderId },
      include: { items: true },
    });

    if (!order) return;

    await prisma.order.update({
      where: { id: orderId },
      data: {
        status: OrderStatus.CANCELLED,
        paymentStatus: PaymentStatus.FAILED,
      },
    });

    // Release reserved inventory back to stock pool
    await inventoryService.releaseInventory(
      order.id,
      PRIMARY_LOCATION_ID,
      order.items.map(i => ({ variantId: i.variantId, quantity: i.quantity }))
    );

    console.log(`[ORDER CANCELLED] Order ${orderId} failed payment. Reason: ${reason || 'Unknown'}`);
  }

  /**
   * DISPATCH / FULFILL ORDER
   */
  public async fulfillOrder(orderId: string, trackingNumber: string, carrier: string): Promise<void> {
    await prisma.order.update({
      where: { id: orderId },
      data: {
        status: OrderStatus.SHIPPED,
        trackingNumber,
        carrier,
      },
    });

    // Trigger shipment notification dispatch
    console.log(`[SHIPMENT NOTIFICATION] Order ${orderId} dispatched via ${carrier}. Tracking: ${trackingNumber}`);
  }

  private async sendOrderConfirmationEmail(email: string, orderNumber: string) {
    // Integration point with SES / SendGrid / Postmark transactional email provider
    console.log(`[TRANSACTIONAL EMAIL SENT] Order Confirmation -> ${email} (Order: ${orderNumber})`);
  }
}
