## 5. API Controller Routes (`orderRoutes.ts`)

Demonstrates express API endpoints exposing these backend services to the Next.js frontend checkout drawer and account dashboards created in the previous task.

```typescript
import { Router, Request, Response } from 'express';
import { OrderProcessingService } from './OrderProcessingService';
import { PaymentService } from './PaymentService';

const router = Router();
const orderProcessingService = new OrderProcessingService();
const paymentService = new PaymentService();

/**
 * POST /api/v1/orders/checkout
 * Initiate checkout, validate prices, reserve inventory, create payment intent
 */
router.post('/checkout', async (req: Request, res: Response) => {
  try {
    const checkoutData = req.body;
    const result = await orderProcessingService.createOrder(checkoutData);

    return res.status(201).json({
      success: true,
      data: result,
    });
  } catch (error: any) {
    console.error('Checkout Processing Error:', error);
    return res.status(400).json({
      success: false,
      message: error.message || 'Failed to process order creation',
    });
  }
});

/**
 * POST /api/v1/orders/:id/refund
 * Administrative endpoint for processing refunds
 */
router.post('/:id/refund', async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { amount } = req.body;

    const refunded = await paymentService.processRefund(id, amount);

    return res.status(200).json({
      success: refunded,
      message: refunded ? 'Refund processed successfully' : 'Refund failed',
    });
  } catch (error: any) {
    return res.status(500).json({
      success: false,
      message: error.message,
    });
  }
});

export default router;
