describe('Backend API Order Processing & Security Tests', () => {

  beforeAll(async () => {
    // Database connection verification
    await prisma.$connect();
  });

  afterAll(async () => {
    await prisma.$disconnect();
  });

  test('SECURITY: Reject client-side price tampering attempts', async () => {
    const maliciousPayload = {
      customerEmail: 'attacker@example.com',
      items: [
        {
          variantId: 'v1-test-uuid', // Active variant priced at $149.99
          quantity: 1,
          price: 0.01 // Manipulated client price attempt
        }
      ],
      shippingAddress: {
        firstName: 'Bad',
        lastName: 'Actor',
        addressLine1: '1 Key Way',
        city: 'Metropolis',
        state: 'NY',
        postalCode: '10001',
        country: 'US'
      },
      shippingMethod: 'STANDARD'
    };

    const response = await request(app)
      .post('/api/v1/orders/checkout')
      .send(maliciousPayload);

    expect(response.status).toBe(201);
    expect(response.body.success).toBe(true);

    // Total MUST NOT be $0.01. It must reflect true server calculation ($149.99 + tax).
    expect(response.body.data.grandTotal).toBeGreaterThan(150.00);
